target.css:
:root {
  --ink: #17233a;
  --paper: #fffdf7;
  --navy: #21385d;
  --line: #d9dfeb;
  --mist: #eef2f8;
  --blue: #3d70d8;
  --aqua: #56c9bf;
  --gold: #f4b544;
  --coral: #ed6c62;
  --muted: #71809a;
}

* {
  box-sizing: border-box;
}

.cue-console {
  width: 500px;
  max-width: 100%;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.console-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 58px;
  padding: 10px 16px;
  background: var(--navy);
  color: var(--paper);
}

.show-meta p,
.timeline-header p {
  margin: 0;
}

.eyebrow {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  line-height: 1.2;
}

.show-meta .eyebrow {
  color: var(--aqua);
}

.show-meta h1,
.timeline-header h2,
.cue-nav h2 {
  margin: 3px 0 0;
  font-size: 17px;
  line-height: 1.05;
}

.live-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--coral);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .7px;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--paper);
}

.cue-body {
  display: grid;
  grid-template-columns: 148px 1fr;
  min-height: 166px;
}

.cue-nav {
  padding: 12px 10px;
  border-right: 1px solid var(--line);
  background: var(--mist);
}

.cue-nav h2 {
  margin: 0 0 8px 5px;
  font-size: 12px;
}

.cue-nav ul {
  display: grid;
  gap: 3px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.nav-item {
  display: grid;
  grid-template-columns: 16px 1fr auto;
  align-items: center;
  padding: 6px 5px;
  border-radius: 6px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.nav-item span {
  color: var(--blue);
  font-size: 9px;
}

.nav-item b {
  font-size: 10px;
}

.nav-item.active {
  background: var(--paper);
  color: var(--navy);
}

.operator {
  margin: 11px 5px 0;
  padding-top: 8px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

.operator strong {
  color: var(--ink);
  font-size: 11px;
}

.cue-main {
  padding: 12px 14px;
}

.timeline-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--line);
}

.timeline-header .eyebrow {
  color: var(--blue);
}

.timeline-header h2 {
  font-size: 15px;
}

.timecode {
  padding: 4px 6px;
  border-radius: 5px;
  background: var(--ink);
  color: var(--gold);
  font-size: 11px;
  font-weight: 800;
}

.cue-list {
  display: grid;
  gap: 4px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.cue-row {
  display: grid;
  grid-template-columns: 25px 1fr 38px 36px;
  align-items: center;
  min-height: 29px;
  padding: 3px 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 11px;
}

.cue-number {
  color: var(--blue);
  font-weight: 800;
}

.cue-name {
  font-weight: 700;
}

.cue-note,
.state {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  text-align: right;
}

.completed {
  background: var(--mist);
}

.completed .state {
  color: var(--aqua);
}

.current {
  border-color: var(--gold);
  background: var(--paper);
}

.current button {
  border: 0;
  border-radius: 4px;
  padding: 4px 0;
  background: var(--gold);
  color: var(--ink);
  font-size: 9px;
  font-weight: 900;
}

.console-footer {
  display: flex;
  justify-content: space-between;
  padding: 8px 16px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
}

.console-footer strong {
  color: var(--navy);
}

